const $=id=>document.getElementById(id);let loggedIn=false,refreshing=false,printing=false,jobs=[],lastKey='';const settings=new Map();
const labels={waiting:'인쇄 대기',printing:'출력 확인 필요',printed:'출력 완료'};
async function api(path,options={}){const response=await fetch('/api/gallery/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok){const error=new Error(data.error||'요청 실패');error.status=response.status;throw error;}return data;}
function showLogin(){loggedIn=false;lastKey='';jobs=[];$('jobs').replaceChildren();$('dashboard').hidden=true;$('login-panel').hidden=false;}
async function state(id,value){await api(`web-print/${id}/state`,{method:'POST',body:JSON.stringify({state:value})});}
function render(){const key=JSON.stringify(jobs);if(key===lastKey)return;lastKey=key;$('jobs').replaceChildren();if(!jobs.length){const p=document.createElement('p');p.textContent='인쇄 접수된 사진이 없습니다. 아이패드에서 사진 인쇄를 누르면 여기에 표시됩니다.';$('jobs').append(p);return;}
for(const job of jobs){let option=settings.get(job.id);if(!option){option={copies:1,scale:94,rotation:0};settings.set(job.id,option);}const article=document.createElement('article');article.className='job';article.dataset.id=job.id;const picture=document.createElement('div');picture.className='picture';const img=new Image();img.src=`/api/gallery/web-print/${job.id}/image`;img.alt='인쇄용 완성 사진';img.loading='lazy';const preview=document.createElement('canvas');preview.hidden=true;picture.append(img,preview);const title=document.createElement('h2');title.textContent=new Date(job.createdAt).toLocaleString('ko-KR');const meta=document.createElement('p');meta.className='meta';meta.textContent='사진 번호 '+job.id.slice(-6)+' · '+new Date(job.expiresAt).toLocaleString('ko-KR')+'까지';const status=document.createElement('p');status.className='state '+job.state;status.textContent=labels[job.state]||labels.waiting;const form=document.createElement('div');form.className='settings';
for(const [key,text,min,max] of [['copies','매수',1,10],['scale','배율 %',85,100]]){const label=document.createElement('label');label.textContent=text;const input=document.createElement('input');input.type='number';input.min=min;input.max=max;input.step=1;input.value=option[key];input.setAttribute('aria-label',text);input.oninput=()=>{option[key]=Number(input.value);};label.append(input);form.append(label);}
const actions=document.createElement('div');actions.className='actions';const print=document.createElement('button');print.className='primary print';print.textContent=job.state==='printed'?'다시 인쇄':'사진 인쇄';print.disabled=printing;print.onclick=()=>printJob(job,option,img,print);const turn=document.createElement('button');turn.className='rotate';function rotatePreview(){turn.textContent=option.rotation===90?'원본 방향으로':'세로로 회전';if(!img.naturalWidth)return;turn.hidden=img.naturalWidth<=img.naturalHeight&&option.rotation===0;const rotated=option.rotation===90;img.hidden=rotated;preview.hidden=!rotated;if(rotated){preview.width=img.naturalHeight;preview.height=img.naturalWidth;const c=preview.getContext('2d');c.translate(preview.width,0);c.rotate(Math.PI/2);c.drawImage(img,0,0);}}img.onload=rotatePreview;img.onerror=()=>{$('status').textContent='사진을 불러오지 못했습니다. 인터넷 연결을 확인하고 새로고침해 주세요.';};turn.onclick=()=>{option.rotation=option.rotation===90?0:90;rotatePreview();};rotatePreview();const done=document.createElement('button');done.className='complete';done.textContent='출력 완료';done.disabled=job.state==='printed';done.onclick=async()=>{done.disabled=true;try{await state(job.id,'printed');await refresh();}catch(e){$('status').textContent=e.message;done.disabled=false;}};const wait=document.createElement('button');wait.textContent='대기로 돌리기';wait.hidden=job.state==='waiting';wait.onclick=async()=>{try{await state(job.id,'waiting');await refresh();}catch(e){$('status').textContent=e.message;}};actions.append(print,turn,done,wait);article.append(picture,title,meta,status,form,actions);$('jobs').append(article);}}
async function refresh(){if(!loggedIn||refreshing||printing)return;refreshing=true;try{const data=await api('web-print');jobs=data.jobs;$('queue-count').textContent=`전체 ${jobs.length}장 · 대기 ${jobs.filter(j=>j.state!=='printed').length}장`;$('updated').textContent='갱신 '+new Date().toLocaleTimeString('ko-KR');render();}catch(e){if(e.status===401)showLogin();$('status').textContent=e.message;}finally{refreshing=false;}}
async function printJob(job,option,img,button){if(printing)return;if(!Number.isInteger(option.copies)||option.copies<1||option.copies>10||!Number.isInteger(option.scale)||option.scale<85||option.scale>100){$('status').textContent='매수는 1~10, 배율은 85~100 사이의 정수를 입력해 주세요.';return;}printing=true;button.disabled=true;let reserved=false;try{await img.decode();await state(job.id,'printing');reserved=true;const canvas=document.createElement('canvas'),rotate=option.rotation===90;canvas.width=rotate?img.naturalHeight:img.naturalWidth;canvas.height=rotate?img.naturalWidth:img.naturalHeight;const c=canvas.getContext('2d');if(rotate){c.translate(canvas.width,0);c.rotate(Math.PI/2);}c.drawImage(img,0,0);const source=canvas.toDataURL('image/jpeg',.98);$('print-sheet').replaceChildren();for(let n=0;n<option.copies;n++){const sheet=document.createElement('div');sheet.className='sheet';const photo=new Image();photo.src=source;photo.style.width=100*option.scale/100+'mm';photo.style.height=148*option.scale/100+'mm';sheet.append(photo);$('print-sheet').append(sheet);await photo.decode();}$('status').textContent='인쇄창에서 CP1500 · Postcard · 여백 없음 · 배율 100% · 매수 1을 선택하세요. 용지가 나오면 출력 완료를 눌러 주세요.';window.print();}catch(e){$('print-sheet').replaceChildren();if(reserved)await state(job.id,'waiting').catch(()=>{});$('status').textContent=e.message||'인쇄 준비에 실패했습니다.';}finally{printing=false;button.disabled=false;lastKey='';await refresh();}}
window.addEventListener('afterprint',()=>{$('print-sheet').replaceChildren();});
$('login-form').onsubmit=async event=>{event.preventDefault();$('login-button').disabled=true;try{await api('unlock',{method:'POST',body:JSON.stringify({code:$('password').value})});$('password').value='';loggedIn=true;$('login-panel').hidden=true;$('dashboard').hidden=false;$('status').textContent='로그인되었습니다.';await refresh();}catch(e){$('status').textContent=e.message;}finally{$('login-button').disabled=false;}};
$('logout').onclick=async()=>{if(printing)return;try{await api('logout',{method:'POST'});showLogin();$('print-sheet').replaceChildren();$('status').textContent='로그아웃되었습니다.';}catch(e){$('status').textContent=e.message;}};
$('refresh').onclick=()=>{lastKey='';void refresh();};
(async()=>{try{const config=await api('config');if(config.authorized){loggedIn=true;$('login-panel').hidden=true;$('dashboard').hidden=false;await refresh();}}catch(e){$('status').textContent=e.message;}})();setInterval(()=>void refresh(),10000);
